import * as ui from './categories/ui.js';
import * as navigation from './categories/navigation.js';
import * as development from './categories/development.js';
import * as files from './categories/files.js';
import * as symbols from './categories/symbols.js';
import * as communication from './categories/communication.js';
import * as media from './categories/media.js';
import * as devices from './categories/devices.js';
import * as weather from './categories/weather.js';
import * as commerce from './categories/commerce.js';
import * as lifestyle from './categories/lifestyle.js';
import { defineIconPack } from './core/define-pack.js';
import { MOEXI_ICON_SPEC_VERSION } from './core/spec.js';
import { createIconRegistry } from './core/registry.js';
export const coreCategories = Object.freeze({
    ui: Object.freeze(Object.values(ui)),
    navigation: Object.freeze(Object.values(navigation)),
    development: Object.freeze(Object.values(development)),
    files: Object.freeze(Object.values(files)),
    symbols: Object.freeze(Object.values(symbols)),
    communication: Object.freeze(Object.values(communication)),
    media: Object.freeze(Object.values(media)),
    devices: Object.freeze(Object.values(devices)),
    weather: Object.freeze(Object.values(weather)),
    commerce: Object.freeze(Object.values(commerce)),
    lifestyle: Object.freeze(Object.values(lifestyle)),
});
export const coreIcons = Object.freeze(Object.values(coreCategories).flatMap((icons) => [...icons]));
export const corePack = defineIconPack({
    name: 'moexi-core',
    version: '1.1.1',
    specVersion: MOEXI_ICON_SPEC_VERSION,
    icons: coreIcons,
    metadata: {
        description: 'The official Moexi core icon collection.',
        license: 'MIT',
    },
});
/** Creates a fresh registry so consumers never share mutable registry state. */
export function createCoreRegistry() {
    return createIconRegistry({ packs: [corePack] });
}
